#include "observatory/observatory.h"
#include <inttypes.h>
#include <stdio.h>
static void report(const observatory_t*o,uint16_t id){observatory_snapshot_t s;if(!observatory_get_snapshot(o,id,&s))return;printf("task=%u jobs=%" PRIu32 " misses=%" PRIu32 " exec[min/avg/max]=%" PRIu32 "/%" PRIu32 "/%" PRIu32 " budget_violations=%" PRIu32 " stack_warnings=%" PRIu32 " headroom=%" PRIu32 " events=0x%02" PRIx32 "\n",s.task_id,s.completed_jobs,s.deadline_misses,s.execution_min_ticks,s.execution_average_ticks,s.execution_max_ticks,s.execution_budget_violations,s.stack_warnings,s.last_stack_headroom,s.event_flags);}
int main(void){observatory_t o;observatory_task_config_t sensor={1U,10U,8U,5U,16U};observatory_task_config_t control={2U,5U,4U,3U,24U};observatory_init(&o);if(!observatory_register_task(&o,sensor,0U)||!observatory_register_task(&o,control,0U)){fputs("registration failed\n",stderr);return 1;}(void)observatory_record_job(&o,1U,1U,6U,32U);(void)observatory_record_job(&o,1U,11U,19U,32U);(void)observatory_record_job(&o,1U,21U,25U,8U);(void)observatory_record_job(&o,2U,1U,3U,40U);(void)observatory_record_job(&o,2U,6U,12U,12U);puts("FreeRTOS observatory — deterministic host simulation");report(&o,1U);report(&o,2U);puts("Simulation only: target timing and physical stack usage are not implied.");return 0;}
